mapper.update:
update estimate_index_links
set update_time = now()

    ,estimate_items_id = #{estimateItemsId}


    ,estimate_index_id = #{estimateIndexId}


    ,estimate_scheme_id = #{estimateSchemeId}


    ,serial_number = #{serialNumber}

where estimate_index_link_id = #{estimateIndexLinkId}

mapper.select:
select * from estimate_index_links
where 1=1

    and estimate_scheme_id = #{schemeId}


    and estimate_items_id = #{estimateItemsId}

order by serial_number asc

mapper.delete:
delete from estimate_index_links
where estimate_index_link_id in

    #{item}
